import { lazy } from 'react';
import { Map as IcMap, Truck as IcTruck, Undo2 as IcUndo2 } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Logistics & Returns — hub page for the Inventory menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 3 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'LogisticsCenter'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const LogisticsShipping = lazy(() => import('./LogisticsShipping'));
const RoutePlanning = lazy(() => import('./RoutePlanning'));
const ReturnsRMA = lazy(() => import('./ReturnsRMA'));

export const TABS = [
  { id: 'shipping', label: 'Logistics', icon: IcTruck, page: 'LogisticsShipping', Component: LogisticsShipping },
  { id: 'routes', label: 'Route Planning', icon: IcMap, page: 'RoutePlanning', Component: RoutePlanning },
  { id: 'returns', label: 'Returns & RMA', icon: IcUndo2, page: 'ReturnsRMA', Component: ReturnsRMA },
];

export default function LogisticsCenter({ setPage }) {
  return (
    <TabHub
      icon={IcTruck}
      eyebrow="Inventory"
      title="Logistics & Returns"
      subtitle="Outbound shipping, route and carrier planning, and the RMA desk"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
